# PTX source for L2‑normalisation (half → half)
PTX_SOURCE = r"""
.version 7.2
.target sm_80
.address_size 64

.visible .entry l2norm_kernel(
    .param .u64 X_PTR,
    .param .u64 Y_PTR,
    .param .u32 BATCH,
    .param .u32 DIM
)
{
    // ------------------------------
    // registers
    // ------------------------------
    .reg .s32  %r<13>;
    .reg .s64  %rd<15>;
    .reg .f32  %f<9>;
    .reg .f16  %h0;
    .reg .pred %p<2>;

    // ------------------------------
    // load kernel parameters
    // ------------------------------
    ld.param.u64 %rd0, [X_PTR];
    ld.param.u64 %rd1, [Y_PTR];
    ld.param.u32 %r0,  [BATCH];
    ld.param.u32 %r1,  [DIM];

    // thread / block indices
    mov.u32 %r2, %ctaid.x;        // row index
    mov.u32 %r3, %tid.x;          // lane index
    mov.u32 %r4, %ntid.x;         // blockDim.x

    // compute base byte offset for this row: row * DIM * sizeof(half)
    mul.lo.u32 %r5, %r2, %r1;               // row * DIM   (fits 32‑bit for our sizes)
    mul.wide.u32 %rd2, %r5, 2;              // *2  (bytes per half)

    // -------------------------------------------------
    // FIRST PASS: compute sum of squares (fp32)
    // -------------------------------------------------
    mov.f32 %f0, 0f00000000;                // partial sum = 0

    // i = lane index
    mov.u32 %r6, %r3;
LOOP_SUM:
    setp.ge.u32 %p0, %r6, %r1;
    @%p0 bra END_SUM;

    // address = X_PTR + (row*DIM + i) * 2
    mul.wide.u32 %rd3, %r6, 2;              // i*2
    add.u64 %rd4, %rd2, %rd3;               // row_offset + i*2
    add.u64 %rd5, %rd0, %rd4;               // global address

    ld.global.f16 %h0, [%rd5];              // load half
    cvt.f32.f16 %f1, %h0;                   // to fp32
    mul.f32 %f2, %f1, %f1;                  // square
    add.f32 %f0, %f0, %f2;                  // accumulate

    // i += blockDim.x
    add.u32 %r6, %r6, %r4;
    bra LOOP_SUM;
END_SUM:

    // ------------------------------
    // reduction in shared memory
    // ------------------------------
    .shared .align 4 .b8 sdata[256*4];      // 256 * float

    // store partial sum to shared memory
    mul.wide.u32 %rd6, %r3, 4;               // offset (bytes) for this thread
    st.shared.f32 [%rd6], %f0;
    bar.sync 0;

    // binary tree reduction (blockDim.x assumed 256)
    // offsets: 128,64,32,16,8,4,2,1
    .reg .u32 %r7;
    .reg .f32 %f3;
    .reg .u64 %rd7, %rd8;

    // macro to reduce by OFFSET
    #define REDUCE(OFFSET)                                      \
        mov.u32 %r7, OFFSET;                                    \
        setp.ge.u32 %p1, %r3, %r7;                              \
        @%p1 {                                                  \
            ld.shared.f32 %f3, [%rd6];                          \
            mul.wide.u32 %rd7, %r7, 4;                          \
            add.u64 %rd8, %rd6, %rd7;                           \
            ld.shared.f32 %f4, [%rd8];                          \
            add.f32 %f3, %f3, %f4;                              \
            st.shared.f32 [%rd6], %f3;                          \
        }                                                        \
        bar.sync 0;

    REDUCE(128)
    REDUCE(64)
    REDUCE(32)
    REDUCE(16)
    REDUCE(8)
    REDUCE(4)
    REDUCE(2)
    REDUCE(1)

    // thread 0 now holds total sum at sdata[0]
    ld.shared.f32 %f4, [0];
    sqrt.approx.f32 %f4, %f4;      // sqrt(sum)
    rcp.approx.f32 %f4, %f4;       // 1 / sqrt(sum)  ->  inv_norm
    st.shared.f32 [0], %f4;        // broadcast
    bar.sync 0;
    ld.shared.f32 %f4, [0];        // %f4 = inv_norm for all lanes

    // -------------------------------------------------
    // SECOND PASS: write normalised values
    // -------------------------------------------------
    mov.u32 %r6, %r3;                 // i = lane index again
LOOP_WRITE:
    setp.ge.u32 %p0, %r6, %r1;
    @%p0 bra END_WRITE;

    mul.wide.u32 %rd3, %r6, 2;        // i*2
    add.u64 %rd4, %rd2, %rd3;         // row_offset + i*2
    add.u64 %rd5, %rd0, %rd4;         // src address
    ld.global.f16 %h0, [%rd5];
    cvt.f32.f16 %f1, %h0;
    mul.f32 %f1, %f1, %f4;            // * inv_norm
    cvt.f16.f32 %h0, %f1;
    add.u64 %rd6, %rd1, %rd4;         // dst address
    st.global.f16 [%rd6], %h0;

    add.u32 %r6, %r6, %r4;            // i += blockDim.x
    bra LOOP_WRITE;
END_WRITE:
    ret;
}
"""

# -------------------------------------------------
# PyTorch wrapper that launches the PTX kernel
# -------------------------------------------------
import torch
import torch.nn as nn
from ptx_harness import ptx_load, ptx_launch

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # x is assumed to be float16
        assert x.dtype == torch.float16
        batch, dim = x.shape
        out = torch.empty_like(x)

        # launch configuration
        grid  = (batch, 1, 1)          # one block per row
        block = (256, 1, 1)            # 256 threads per block

        args = [
            x.data_ptr(),              # X_PTR
            out.data_ptr(),            # Y_PTR
            batch,                     # BATCH
            dim                        # DIM
        ]

        ptx_launch(self.module, "l2norm_kernel", grid, block, args)
        return out
